[metadata] {"type": "create", "filePath": "/workspace/repo/packages/cli/src/studio-server.ts", "content": "import { createServer, type IncomingMessage, type ServerResponse } from 'node:http'

/**
 * A running Studio HTTP server.
 */
export type StudioServer = {
  /**
   * Stops the server from accepting new connections.
   */
  close(): void
}

/**
 * Options for {@link startStudioServer}.
 */
export type StudioServerOptions = {
  /**
   * Handles an incoming request and produces the response to send back.
   */
  handler: (request: Request) => Response | Promise<Response>

  /**
   * Invoked once the server is ready to accept connections.
   */
  onListen: () => void

  /**
   * The port to listen on.
   */
  port: number
}

/**
 * Starts an HTTP server that delegates incoming requests to `handler`.
 *
 * `GET` requests are forwarded to `handler` and their status and body are
 * streamed back to the client. `HEAD` requests reuse the response of the
 * equivalent `GET` request but with an empty body. When `handler` throws, the
 * server responds with HTTP 500 and the error message as the plain-text body.
 */
export function startStudioServer({ handler, onListen, port }: StudioServerOptions): StudioServer {
  const server = createServer((req, res) => {
    void handleRequest(req, res, handler)
  })

  server.listen(port, onListen)

  return {
    close() {
      server.close()
    },
  }
}

async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse,
  handler: StudioServerOptions['handler'],
): Promise<void> {
  const method = (req.method ?? 'GET').toUpperCase()
  const isHead = method === 'HEAD'
  const requestMethod = isHead ? 'GET' : method

  const host = req.headers.host ?? 'localhost'
  const url = `http://${host}${req.url ?? '/'}`

  const headers = new Headers()

  for (const [key, value] of Object.entries(req.headers)) {
    if (value === undefined) {
      continue
    }

    if (Array.isArray(value)) {
      for (const item of value) {
        headers.append(key, item)
      }
    } else {
      headers.set(key, value)
    }
  }

  const hasBody = requestMethod !== 'GET' && requestMethod !== 'HEAD'
  const body = hasBody ? await readRequestBody(req) : undefined

  const request = new Request(url, { body, headers, method: requestMethod })

  try {
    const response = await handler(request)

    await sendResponse(res, response, isHead)
  } catch (error) {
    console.error('[Prisma Studio]', error)

    const message = error instanceof Error ? error.message : String(error)

    res.writeHead(500, {
      'access-control-allow-origin': '*',
      'content-type': 'text/plain; charset=utf-8',
    })
    res.end(isHead ? undefined : message)
  }
}

async function readRequestBody(req: IncomingMessage): Promise<Buffer | undefined> {
  const chunks: Buffer[] = []

  for await (const chunk of req) {
    chunks.push(chunk as Buffer)
  }

  return chunks.length === 0 ? undefined : Buffer.concat(chunks)
}

async function sendResponse(res: ServerResponse, response: Response, isHead: boolean): Promise<void> {
  const headers: Record<string, string> = {}

  response.headers.forEach((value, key) => {
    headers[key] = value
  })

  res.writeHead(response.status, headers)

  if (isHead || response.body === null) {
    res.end()
    return
  }

  res.end(Buffer.from(await response.arrayBuffer()))
}
