/**
 * CORS headers applied to every Studio BFF response.
 */
const CORS_PREFLIGHT_HEADERS = {
  'access-control-allow-headers': 'Content-Type',
  'access-control-allow-methods': 'GET, HEAD, POST, OPTIONS',
  'access-control-allow-origin': '*',
} as const

/**
 * Starts the Studio BFF HTTP server, wrapping the Hono `app` so that every
 * response carries the `access-control-allow-origin: *` header and `OPTIONS`
 * preflight requests are answered with an empty HTTP 204 response.
 */
function startStudioBff(app: Hono, port: number, onListen: () => void) {
  return startStudioServer({
    handler: async (request) => {
      if (request.method === 'OPTIONS') {
        return new Response(null, { headers: CORS_PREFLIGHT_HEADERS, status: 204 })
      }

      const response = await app.fetch(request)

      const headers = new Headers(response.headers)
      headers.set('access-control-allow-origin', '*')

      return new Response(response.body, {
        headers,
        status: response.status,
        statusText: response.statusText,
      })
    },
    onListen,
    port,
  })
